import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AlertProps } from "./alert.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { IconButtonClasses } from "@components/icon-button";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Alert";

// Generate child element class names for the component, should match available style slots
export const AlertClasses = {
  root: "exp-textura_alert",
  icon: "exp-textura_alert_icon",
  closeIconButton: "exp-textura_alert_close_icon_button",
  content: "exp-textura_alert_contents",
  title: "exp-textura_alert_title",
  description: "exp-textura_alert_description",
  edge: "exp-textura_alert_edge",
  inline: "exp-textura_alert_inline",
  sm: "exp-textura_alert_sm",
  subtle: "exp-textura_alert_subtle",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      backgroundColor: theme.alert.bold.critical.color.background,
      color: theme.alert.bold.critical.color.content,
    },
    icon: {
      color: theme.color.content.inverse,
    },
    subtle: {
      backgroundColor: theme.alert.subtle.critical.color.background,
      color: theme.alert.subtle.critical.color.content,
    },
    subtleIcon: {
      color: theme.color.content.utility.critical,
    },
    closeIconButton: {
      color: theme.alert.bold.critical.color.content,
    },
    subtleCloseIconButton: {
      color: theme.buttonIcon.secondary.color.content.enabled,
    },
  },
  info: {
    root: {
      backgroundColor: theme.alert.bold.info.color.background,
      color: theme.alert.bold.info.color.content,
    },
    icon: {
      color: theme.color.content.inverse,
    },
    subtle: {
      backgroundColor: theme.alert.subtle.info.color.background,
      color: theme.alert.subtle.info.color.content,
    },
    subtleIcon: {
      color: theme.color.content.utility.info,
    },
    closeIconButton: {
      color: theme.alert.bold.info.color.content,
    },
    subtleCloseIconButton: {
      color: theme.buttonIcon.secondary.color.content.enabled,
    },
  },
  neutral: {
    root: {
      backgroundColor: theme.alert.bold.neutral.color.background,
      color: theme.alert.bold.neutral.color.content,
    },
    icon: {
      color: theme.color.content.inverse,
    },
    subtle: {
      backgroundColor: theme.alert.subtle.neutral.color.background,
      color: theme.alert.subtle.neutral.color.content,
    },
    subtleIcon: {
      color: theme.color.content.utility.neutral,
    },
    closeIconButton: {
      color: theme.alert.bold.neutral.color.content,
    },
    subtleCloseIconButton: {
      color: theme.buttonIcon.secondary.color.content.enabled,
    },
  },
  success: {
    root: {
      backgroundColor: theme.alert.bold.success.color.background,
      color: theme.alert.bold.success.color.content,
    },
    icon: {
      color: theme.color.content.inverse,
    },
    subtle: {
      backgroundColor: theme.alert.subtle.success.color.background,
      color: theme.alert.subtle.success.color.content,
    },
    subtleIcon: {
      color: theme.color.content.utility.success,
    },
    closeIconButton: {
      color: theme.alert.bold.success.color.content,
    },
    subtleCloseIconButton: {
      color: theme.buttonIcon.secondary.color.content.enabled,
    },
  },
  warning: {
    root: {
      backgroundColor: theme.alert.bold.warning.color.background,
      color: theme.alert.bold.warning.color.content,
    },
    icon: {
      color: theme.color.content.strong,
    },
    subtle: {
      backgroundColor: theme.alert.subtle.warning.color.background,
      color: theme.alert.subtle.warning.color.content,
    },
    subtleIcon: {
      color: theme.color.transparency.black[55],
    },
    closeIconButton: {
      color: theme.buttonIcon.primary.color.content.enabled,
    },
    subtleCloseIconButton: {
      color: theme.buttonIcon.secondary.color.content.enabled,
    },
  },
});

const generateStyles = (props: AlertProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AlertProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    position: "relative",
    display: "flex",
    flex: "1",
    alignItems: "flex-start",
    backgroundColor: theme.alert.bold.attention.color.background,
    color: theme.alert.bold.attention.color.content,
    gap: theme.toRem(theme.spacing[8]),
    padding: theme.toRem(theme.spacing[16]),

    [`&.${AlertClasses.edge}`]: {
      borderRadius: 0,
      ...styleSlots?.edge,
    },
    [`&.${AlertClasses.inline}`]: {
      borderRadius: theme.toRem(theme.border.radius.sm),
      ...styleSlots?.inline,
    },
    [`&.${AlertClasses.sm}`]: {
      borderRadius: theme.toRem(theme.border.radius.sm),
      padding: theme.toRem(theme.spacing[8]),
      [`> .${AlertClasses.icon}`]: {
        height: theme.toRem(16),
        minWidth: theme.toRem(16),
        marginTop: theme.toRem(theme.spacing[4]),
        paddingInlineEnd: 0,
        ...styleSlots?.smallIcon,
      },
      [`> .${AlertClasses.title}`]: {
        ...theme.typography.label.sm,
        ...styleSlots?.smallTitle,
      },
      [`> .${AlertClasses.description}`]: {
        ...theme.typography.body.sm,
        ...styleSlots?.smallDescription,
      },
      ...styleSlots?.small,
    },
    [`&.${AlertClasses.subtle}`]: {
      backgroundColor: theme.alert.subtle.attention.color.background,
      color: theme.alert.subtle.attention.color.content,
      [`> .${AlertClasses.icon}`]: {
        color: theme.color.content.utility.attention,
        ...styleSlots?.subtleIcon,
      },
      [`> .${AlertClasses.closeIconButton}`]: {
        color: theme.buttonIcon.secondary.color.content.enabled,
        ...styleSlots?.subtleCloseIconButton,
      },
      ...styleSlots?.subtle,
    },

    [`.${AlertClasses.icon}`]: {
      marginTop: theme.toRem(2),
      height: theme.toRem(20),
      minWidth: theme.toRem(20),
      paddingInlineEnd: theme.toRem(theme.spacing[4]),
      color: theme.color.content.inverse,
      ...styleSlots?.icon,
    },

    [`.${AlertClasses.closeIconButton}`]: {
      flexShrink: 0,
      [`&.${IconButtonClasses.secondary}`]: {
        color: "inherit",
        ":hover": {
          color: "inherit",
        },
      },
      marginInlineEnd: theme.toRem(-6),
      marginInlineStart: theme.toRem(6),
      marginTop: theme.toRem(-6),
      marginBottom: theme.toRem(6),
      ...styleSlots?.closeIconButton,
    },

    [`.${AlertClasses.content}`]: {
      flex: "1 1 auto",
      display: "flex",
      flexDirection: "column",
      ...styleSlots?.content,
    },

    [`.${AlertClasses.title}`]: {
      all: "unset",
      ...theme.typography.label.md,
      ...styleSlots?.title,
    },

    [`.${AlertClasses.description}`]: {
      all: "unset",
      ...theme.typography.body.md,
      ...styleSlots?.description,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("title");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAlert = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AlertProps>((props) => generateStyles(props));
